using W=System.Windows;
using C=System.Windows.Controls;
namespace BackupReminder;
internal sealed partial class ReviewWindow
{
 void VerifyScheduleAndSetup(){var results=new List<string>();void Check(bool valid,string label){if(!valid)throw new Exception(label);results.Add("PASS: "+label);}
  var owner=Dialog("Schedule test",780,700,new C.Grid());var panel=BuildReminderPage(owner,out var read);owner.Content=panel;owner.Show();owner.UpdateLayout();var combos=Descendants<C.ComboBox>(owner).ToDictionary(x=>System.Windows.Automation.AutomationProperties.GetName(x));var calendar=Descendants<C.DatePicker>(owner).Single();var interval=Descendants<C.TextBox>(owner).Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="Every (days)");
  var soundSelector=combos["Sound"];var preview=Descendants<C.Button>(owner).Single(x=>Equals(x.Content,"Preview sound"));soundSelector.SelectedItem="Windows default";owner.UpdateLayout();Check(Math.Abs(soundSelector.TranslatePoint(new W.Point(),owner).Y-preview.TranslatePoint(new W.Point(),owner).Y)<0.1&&soundSelector.ActualHeight==preview.ActualHeight,"Sound selector and Preview share exact top and height");
  foreach(string appearance in new[]{"Light","Dark"}){ApplyTheme(appearance);foreach(string key in new[]{"How often","Day of the month","Hour","Minute","AM or PM","Sound"}){var box=combos[key];box.IsDropDownOpen=true;owner.UpdateLayout();var popup=(C.Primitives.Popup)box.Template.FindName("PART_Popup",box);popup.Child.UpdateLayout();owner.Dispatcher.Invoke(()=>{},System.Windows.Threading.DispatcherPriority.ApplicationIdle);popup.Child.UpdateLayout();var viewer=Descendants<C.ScrollViewer>(popup.Child).First();if(viewer.ScrollableHeight==0)Check(Math.Abs(viewer.ActualWidth-((C.ScrollContentPresenter)viewer.Template.FindName("PART_ScrollContentPresenter",viewer)).ActualWidth)<1,"No empty popup gutter: "+appearance+" "+key+" width="+viewer.ActualWidth+" viewport="+viewer.ViewportWidth);else Check(viewer.ComputedVerticalScrollBarVisibility==W.Visibility.Visible,"Overflow popup scrolls: "+appearance+" "+key);box.IsDropDownOpen=false;}}
  combos["How often"].SelectedIndex=0;owner.UpdateLayout();Check(!calendar.IsVisible&&combos["Day of the month"].IsVisible,"Monthly hides interval and starting date");combos["Day of the month"].SelectedItem="31";combos["Hour"].SelectedItem="12";combos["Minute"].SelectedItem="00";combos["AM or PM"].SelectedItem="AM";Check(read().Schedule!.TimeOfDay=="00:00","12 AM saves as midnight");combos["AM or PM"].SelectedItem="PM";Check(read().Schedule!.TimeOfDay=="12:00","12 PM saves as noon");combos["How often"].SelectedIndex=1;owner.UpdateLayout();Check(calendar.IsVisible&&!combos["Day of the month"].IsVisible,"Interval hides monthly day");interval.Text="14";calendar.SelectedDate=new DateTime(2027,2,3);var chosen=read();Check(chosen.Schedule!.IntervalDays==14&&chosen.Schedule.StartDate=="2027-02-03"&&chosen.Schedule.DayOfMonth==31,"Interval preserves canonical date and previous monthly day");Check(ScheduleDescription(chosen.Schedule).Contains("Every 14 days at 12:00 PM, starting 02/03/2027"),"Human-readable interval summary");interval.Text="0";bool invalid=false;try{read();}catch(InvalidDataException){invalid=true;}Check(invalid,"Invalid interval rejected before save");owner.Close();
  foreach(var item in new[]{("0.3.2",true,"Update available"),("0.3.1",false,"You're up to date"),("0.3.0",false,"You're running a newer version")}){var status=ReleaseStatus("{\"tag_name\":\"v"+item.Item1+"\"}",new Version(0,3,1));Check(status.Available==item.Item2&&status.Heading==item.Item3,"Update comparison "+item.Item1);}
  string before=File.ReadAllText(profile.SettingsPath);var setup=SetupWindow();setup.Show();setup.UpdateLayout();var next=Descendants<C.Button>(setup).Single(x=>Equals(x.Content,"Next"));next.RaiseEvent(new W.RoutedEventArgs(C.Button.ClickEvent));setup.UpdateLayout();Capture(setup,Path.Combine(directory,"setup-preferences.png"));next.RaiseEvent(new W.RoutedEventArgs(C.Button.ClickEvent));setup.UpdateLayout();Capture(setup,Path.Combine(directory,"setup-schedule.png"));setup.Close();Check(File.ReadAllText(profile.SettingsPath)==before,"Cancel setup leaves saved configuration unchanged");File.WriteAllLines(Path.Combine(directory,"schedule-setup-verification.txt"),results);
 }
}
